// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(this)); }
    function testFuzz_property(uint128 sendAmt, uint64 unlock, address actor) public {
        vm.assume(actor != address(0));
        uint256 amt = bound(uint256(sendAmt), 0, 5 ether);
        uint256 ul = bound(uint256(unlock), 0, type(uint256).max);

        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(ul);

        assertTrue(getLastMsgSender() == actor);
    }

    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message public LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    function getLastMsgSender() public view returns (address) {
        return LastMsg.Sender;
    }
}
